from taf.internal.aliasing import aliasing_scope
from taf.internal.robot_typecasts.typecasts import time_to_seconds, to_boolean

from taf.gnb.oam.coam.cu.exception import IncorrectParameterValue
from taf.gnb.oam.coam.cu.facade import CUConnection
from taf.gnb.oam.coam.cu.utilities.time_covert import convert_time_format
from taf.gnb.oam.coam.cu.utilities.convert_to_builtin import convert_result_to_builtin_type


@convert_result_to_builtin_type
class cu:
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope('connection', CUConnection, name=__name__)

    """
       Usage example:
           >>> from taf.gnb.oam.coam.cu import cu
           >>> cu_object = cu()
           >>> cu_object.connect_to(host='10.0.10.0', port='8080', username='ExampleName', password='ExamplePassword',
           >>>                      cu_version='cuoam_19b', connection_name='cu_rest_conn', secure=True)
           >>> cu_object.perform_commissioning(scf_file="/home/ute/scf.xml")
           >>> cu_object.disconnect(cu_connection='cu_rest_conn')
       """

    def __init__(self):
        self.login_response = None

    def connect_to(self, host, port, username, password, cu_version='cuoam_26r1', secure=False, login_disabled=False,
                   alias=None, timeout=None, use_m2m=False, read_only=False, update_expired_password=True, log_dir=""):
        """
        Provides connection and authorization to CU.

        .. note::
            **API used:**

            +-------------------+---------------------------------------------+
            | use_m2m           | API Endpoint                                |
            +===================+=============================================+
            | False             | * `POST /api/sec/v1/login`_                 |
            +-------------------+---------------------------------------------+
            | True              | * POST /api/licensed/sec/v1/login           |
            +-------------------+---------------------------------------------+

        :param str host: IP address to proper host, f.e. `127.0.0.1`.
        :param str port: Port for connection to CU.
        :param str username: Username to authenticate to CU.
        :param str password: Password to authenticate to CU.
        :param str cu_version: (optional) Specifies version of the CU.
                               Current possibilities:
                               cuoam_19b, cuoam_21b, cuoam_22r4, cuoam_23r1,
                               cuoam_23r2, cuoam_23r3, cuoam_24r1, cuoam_24r2,
                               cuoam_24r3, cuoam_25r1, cuoam_25r2, cuoam_25r3,
                               cuoam_26r1
                               Defaults to the newest implemented release - cuoam_26r1.
        :param bool secure: (optional) If set to True, the connection will be made using HTTPS protocol, otherwise with HTTP,
                            Defaults to False.
        :param bool login_disabled: (optional) If set to True, default token will be used instead log in. Defaults to False.
        :param str alias: (optional) Name of returned connection. If not provided, this connection becomes "default".
        :param Union[int, str, float] timeout: (optional) Timeout for the operation in seconds
        :param bool use_m2m: (optional) If set to true, M2M login(/api/licensed/sec/v1/login) will be used.
                             Otherwise, internal login(/api/sec/v1/login) is used.
                             Defaults to False.
                             Must set use_m2m -> False when login first time after deployment.
        :param bool read_only: (optional) If set to True, the connection will be read-only. Defaults to False.
        :param bool update_expired_password: (optional) If set to True, expired password will be updated to "Nokia@123".
                                             Otherwise the user can use keyword update_expired_password to
                                             change password on their own. Defaults to True.
        :param str log_dir: (optional) directory where log messages from the library will be saved.
                            Name of the file with logs is "cu_api_debug_{connection_name}.log"
                            When this value is not given logs will be saved in the working directory.

        :returns: CUConnection instance.
        :rtype: CUConnection
        """
        cu_connection = CUConnection(host=host,
                                     port=port,
                                     username=username,
                                     password=password,
                                     cu_version=cu_version,
                                     secure=to_boolean(secure),
                                     login_disabled=to_boolean(login_disabled),
                                     timeout=time_to_seconds(timeout, round_to=0),
                                     use_m2m=to_boolean(use_m2m),
                                     alias=alias if alias else "default",
                                     read_only=to_boolean(read_only),
                                     update_expired_password=to_boolean(update_expired_password),
                                     log_dir=log_dir)

        self.store.add(cu_connection, alias)
        self.login_response = cu_connection.login_response

        return cu_connection

    @lookup_handler.implicit_lookup
    def disconnect(self, connection=None, timeout=10):
        """
        Sends logout request.

        .. note::

           **API used:**

           +-------------------+---------------------------------------------+
           | use_m2m           | API Endpoint                                |
           +===================+=============================================+
           | False             | * `POST /api/sec/v1/logout`_                |
           +-------------------+---------------------------------------------+
           | True              | * POST /api/licensed/sec/v1/logout          |
           +-------------------+---------------------------------------------+

        :param Union[CUConnection, str] connection: (optional) CUConnection object or string name alias if used
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 10s
        """
        connection.disconnect(timeout=time_to_seconds(timeout, round_to=0))
        self.store.remove_object(connection)

    @lookup_handler.implicit_lookup
    def perform_commissioning(self, scf_file, timeout=300, wait_for_completion=True, should_activate=True,
                              connection=None):
        """
        Perform Commissioning

        By default, wait_for_completion is set to True, meaning the keyword will wait until the operation is complete.
        If wait_for_completion is set to False, it is advisable to check the operation's status using
        get_status_of_perform_commissioning to confirm successful activation.

        .. note::

            **API used:**

            +----------------+-----------------+----------------------------------------------------------------------------------+
            | Interface      | should_activate | API Endpoints                                                                    |
            +================+=================+==================================================================================+
            | M2M enabled    | True            | * `POST /api/licensed/v1/staged-plans/operations/provisions`_                    |
            |                |                 | * `GET /api/licensed/v1/staged-plans/operations/provisions/{operationId}`_       |
            +----------------+-----------------+----------------------------------------------------------------------------------+
            | M2M enabled    | False           | * `POST /api/licensed/v1/staged-plans/operations/pre-activations`_               |
            |                |                 | * `GET /api/licensed/v1/staged-plans/operations/pre-activations/{operationId}`_  |
            +----------------+-----------------+----------------------------------------------------------------------------------+
            | M2M disabled   | True            | * `POST /api/asm/v1/staged-plans/actions/downloads`_                             |
            | (first         |                 | * `GET /api/emservice/v1/staged-plans`_                                          |
            | commissioning) |                 | * `POST /api/asm/v1/staged-plans/{planId}/operations/activations`_               |
            |                |                 | * `GET /api/asm/v1/staged-plans/{planId}/operations/activations/{operationId}`_  |
            +----------------+-----------------+----------------------------------------------------------------------------------+
            | M2M disabled   | False           | * `POST /api/asm/v1/staged-plans/actions/downloads`_                             |
            | (first         |                 | * `GET /api/emservice/v1/staged-plans`_                                          |
            | commissioning) |                 |                                                                                  |
            +----------------+-----------------+----------------------------------------------------------------------------------+

        In order to enable M2M interface during this first commissioning please remember to set "actCli" parameter.

        :param str scf_file: path to plan file in XML format
        :param int timeout: (optional) Timeout for the operation, defaults to 300.
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
        :param should_activate: (optional) If set to True, plan will be activated, otherwise it will be validated
                                           without activation. In order to activate the pre-activated plan user
                                           should call plan_activation keyword with pre_activated=True and using "cmPlanId"
                                           field value as plan_id.
                                           Defaults to True.
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections
                                                    or CUConnection instance returned by connect_to.

        :returns: status of operation, for example:

            .. code-block:: python

                {
                    "id": "101",
                    "status": "ongoing"
                }
        :rtype: dict
        """
        return connection.perform_commissioning(scf_file=scf_file,
                                                wait_for_completion=wait_for_completion,
                                                should_activate=should_activate,
                                                timeout=time_to_seconds(timeout, round_to=0))

    @lookup_handler.implicit_lookup
    def get_status_of_perform_commissioning(self, operation_id, connection=None, timeout=30, should_activate=True):
        """
        Get status of perform_commissioning operation.

        If should_activate parameter was set to False when executing perform_commissioning, it
        should also be given as False to properly get the status.

        .. note::

            **API used:**

            +------------------+---------------------------------------------------------------------------------+
            | should_activate  | API Endpoint                                                                    |
            +==================+=================================================================================+
            | True             | * `GET /api/licensed/v1/staged-plans/operations/provisions/{operationId}`_      |
            +------------------+---------------------------------------------------------------------------------+
            | False            | * `GET /api/licensed/v1/staged-plans/operations/pre-activations/{operationId}`_ |
            +------------------+---------------------------------------------------------------------------------+

        :param str operation_id: operation id, get from keyword perform_commissioning
        :param int timeout: (optional) Timeout for the operation, defaults to 30.
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections
                                                    or CUConnection instance returned by connect_to.
        :param bool should_activate: (optional) Should be set to False if perform_commissioning was executed without
                                                activation. Defaults to True.

        :returns: status and error message of operation, for example:

            .. code-block:: python

                {
                    "id": "101",
                    "status": "success",
                    "error_message": ""
                }
        :rtype: dict
        """
        return connection.get_status_of_perform_commissioning(operation_id=operation_id,
                                                              should_activate=should_activate,
                                                              timeout=time_to_seconds(timeout, round_to=0))

    @lookup_handler.implicit_lookup
    def upload_plan_file(self, path_to_plan_file, plan_name="default_plan_name", wait_for_completion=False,
                         timeout=None, connection=None, **kwargs):
        """
        Uploads plan to the "Planned Configuration" section of the staging area

        .. note::

           **API used:**

           +-----------------------------+---------------------------------------------------------------+
           | Condition                   | API Endpoint(s)                                               |
           +=============================+===============================================================+
           | wait_for_completion = True  | POST /api/asm/v1/staged-plans/actions/downloads;              |
           |                             | GET  /api/asm/v1/staged-plans/actions/downloads/{operationId} |
           +-----------------------------+---------------------------------------------------------------+
           | wait_for_completion = False | POST /api/asm/v1/staged-plans/actions/downloads               |
           +-----------------------------+---------------------------------------------------------------+

        .. important::
            The underlying API endpoint for this operation contains "downloads" in its URL
            (e.g., `/api/asm/v1/staged-plans/actions/downloads`).

            On the other hand, the `trigger_download_of_current_plan` keyword utilizes an API endpoint with "uploads" in its URL
            (e.g., `/api/licensed/v1/current-plan/operations/uploads`).

            This apparent inversion stems from a difference in perspective:
                *   API endpoints are typically named from the product's viewpoint
                    (e.g., vDU offers an "upload" endpoint for you to download data from it).
                *   Library keywords are designed from the user's viewpoint (e.g., as a user, you are "downloading" a plan).

            This design choice prioritizes user-centric clarity within the library, abstracting the product's internal API naming conventions.

        :param str path_to_plan_file: Path to file, which should be uploaded, for example: 'home/ute/SCF_vDU_update_trs_668.xml'
        :param str plan_name: (required only for cuoam_19b) the name given to the plan, for example:'vdu_1_plan'
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
        :param Union[float, int, str] timeout: (optional) Timeout for the operation.
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.

        :returns: upload plan operation info, for example:

            .. code-block:: python

                {
                   "raml_parsing_errors":[
                      "ramlParseError1",
                      "ramlParseError2"
                   ],
                   "incorrect_objects_feedback":[
                      {
                         "errorCode":"ParameterWithoutDefinition",
                         "path":"MRBTS-1/MNL-1.cmSyncCheckPerio"
                      },
                      {
                         "errorCode":"ObjectNotAllowedToCreate",
                         "path:":"MRBTS-10999/NRBTS-1/LTEENB-1"
                      }
                   ],
                   "procedure_state":"planDownload",
                   "action_id":101,
                   "links":[
                      {
                         "rel":"self",
                         "herf":"/some/useful/links"
                      }
                   ],
                   "status":"ongoing",
                   "error_message":"error message"
                }
        :rtype: dict
        """
        return connection.upload_plan_file(path_to_plan_file=path_to_plan_file,
                                           plan_name=plan_name,
                                           wait_for_completion=wait_for_completion,
                                           timeout=time_to_seconds(timeout, round_to=0),
                                           **kwargs)

    @lookup_handler.implicit_lookup
    def get_plan_file(self, plan_id, path, connection=None, timeout=10, **kwargs):
        """
        Save staged plan ("Planned Configuration" section in staging area) to the given local path.

        .. note::
           **API used:**

           +--------------------------+---------------------------------------------------------------+
           | Software Version         | API Endpoints                                                 |
           +==========================+===============================================================+
           | Before CB012840          | GET  /api/asm/v1/staged-plans;                                |
           |                          | POST /api/asm/v1/staged-plans/{planId}/actions/uploads;       |
           |                          | GET  /api/asm/v1/staged-plans/{planId}/actions/uploads/       |
           |                          | {operationId};                                                |
           |                          | GET  /api/asm/v1/files/{fileName}                             |
           +--------------------------+---------------------------------------------------------------+
           | After CB012840           | GET  /api/emservice/v1/staged-plans;                          |
           |                          | POST /api/emservice/v1/staged-plans/{planId}/actions/uploads; |
           |                          | GET  /api/emservice/v1/staged-plans/{planId}/actions/uploads/ |
           |                          | {operationId};                                                |
           |                          | GET  /api/emservice/v1/files/{fileName}                       |
           +--------------------------+---------------------------------------------------------------+

        :param str plan_id: ID of the plan, can be taken from upload_plan keyword
        :param str path: Local path where file should be saved, consisting of file name an .xml extension,
                         for example: "/home/ute/Desktop/vdu_plan_1.xml"
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or CUConnection
                                                    instance returned by connect_to.
        :param Union[float, int, str] timeout: (optional) Timeout for the operation, defaults to 10
        :param bool include_auto_config_data: (optional) Whether auto config data should be included in the plan content.
                                              Defaults to False.

        :return: saved plan content
        :rtype: str
        """
        return connection.get_plan_file(plan_id=plan_id, path=path, timeout=time_to_seconds(timeout, round_to=0),
                                        **kwargs)

    @lookup_handler.implicit_lookup
    def plan_delete(self, plan_id, connection=None):
        """
        Remove plan with given ID from "Planned Configuration" section of staging area.

        .. note::
            **API used:**

            DELETE /api/asm/v1/staged-plans/{planId}

        :param str plan_id: ID of the plan, can be taken from upload_plan_file keyword
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.
        """
        connection.plan_delete(plan_id)

