    @lookup_handler.implicit_lookup
    def get_current_plan_file(self, path, include_runtime_data=False, timeout=120, connection=None, **kwargs):
        """
        Triggers download of current plan, waits for operation to complete and saves file to local.

        It is possible to break this operation into separate steps by using:
            1. trigger_download_of_current_plan to trigger download of current plan
            2. get_status_of_current_plan_download to get status of download operation
            3. save_downloaded_plan_to_local to save plan to local

        .. note::

           **API used:**

           +-------------------+-------------------------------------------------------------------------------+
           | Condition         | API Endpoints                                                                 |
           +===================+===============================================================================+
           | use_m2m = False   | * `POST /api/cm/v2/current-plan/operations/uploads`_                          |
           |                   | * `GET  /api/cm/v2/current-plan/operations/uploads/{operationId}`_            |
           |                   | * `GET  /api/cm/v2/current-plan/operations/uploads/{operationId}/file`_       |
           +-------------------+-------------------------------------------------------------------------------+
           | use_m2m = True    | * `POST /api/licensed/v1/current-plan/operations/uploads`_                    |
           |                   | * `GET  /api/licensed/v1/current-plan/operations/uploads/{operationId}`_      |
           |                   | * `GET  /api/licensed/v1/current-plan/operations/uploads/{operationId}/file`_ |
           +-------------------+-------------------------------------------------------------------------------+

        .. important::
            The underlying API endpoint for this operation contains "uploads" in its URL
            (e.g., `/api/licensed/v1/current-plan/operations/uploads`).

            On the other hand, the `upload_plan_file` keyword utilizes an API endpoint with "downloads" in its URL
            (e.g., `/api/asm/v1/staged-plans/actions/downloads`).

            This apparent mismatch stems from a difference in perspective:
                *   API endpoints are typically named from the product's viewpoint
                    (e.g., CU offers an "upload" endpoint for you to download data from it).
                *   Library keywords are designed from the user's viewpoint (e.g., as a user, you are "downloading" a plan).

            This design choice prioritizes user-centric clarity within the library, abstracting the product's internal API naming conventions.

        :param str path: Path where plan should be saved, for example: "/home/ute/Desktop/current_plan.xml"
        :param bool include_runtime_data: (optional) Whether runtime data should be included in uploaded plan content
        :param Union[float, int, str] timeout: (optional) Timeout for the operation. Defaults to 120s
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.
        :param bool include_auto_config_data: (optional) Whether auto config data should be included in the plan.
                                              Defaults to True.
        :param bool use_m2m: (optional, applicable only for release cuoam_21b or newer) If set to False,
                             internal API will be used instead of licensed API (M2M).
                             Defaults to True.

        :return: content of the current plan.
        :rtype: str
        """
        return connection.get_current_plan_file(path=path,
                                                include_runtime_data=include_runtime_data,
                                                timeout=time_to_seconds(timeout, round_to=0),
                                                **kwargs)

