    @lookup_handler.implicit_lookup
    def trigger_local_snapshot(self, connection=None, use_m2m=True, **kwargs):
        """
         Triggers collecting of snapshot

        .. note::

           **API used:**

           +-------------------+----------------------------------------------------+
           | use_m2m           | API Endpoint                                       |
           +===================+====================================================+
           | True              | * `POST /api/licensed/v1/snapshot/operations`_     |
           +-------------------+----------------------------------------------------+
           | False             | * `POST /api/asm/v1/snapshot/operations/locals`_   |
           +-------------------+----------------------------------------------------+

        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                 CUConnection instance returned by connect_to.
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) m2m feature activation flag.
                          If set to False, internal API will be used instead of licensed API (M2M)
                          Defaults set to True.
        :param float request_timeout: (optional) timeout in seconds for sending request to OAM, defaults to 30
        :param list sdl_components: (optional) list of dictionaries with sdl components to be included in snapshot.
                                    Available only for internal API (use_m2m=False). For example:

                                    .. code-block:: python

                                      [
                                          {
                                              "name": "5G-CP-UE",
                                              "namespaces": [
                                                  {"name": "5GCPCpUeConfiguration", "keyPrefixes": ["gNBUEF1APIDRangeIndex_"]},
                                                  {"name": "5GCPCpUeIdentifiers", "keyPrefixes": ["cpueID_"]},
                                              ],
                                          },
                                          {
                                              "name": "5G-CP-E2",
                                              "namespaces": [
                                                  {"name": "5GCPCpTransactionId", "keyPrefixes": ["TransactionIdIndex_"]},
                                                  {"name": "5GCPRicPolicyStorageCa", "keyPrefixes": ["CaPolicyCond_"]},
                                                  {"name": "5GCPRicPolicyStorageImlb", "keyPrefixes": ["ImlbPolicyCond_"]},
                                                  {"name": "5GCPc_plane_cu_rad_config", "keyPrefixes": ["rd_"]},
                                              ],
                                          },
                                      ]

        :param bool include_sdl_history_recordings: (optional) if it is assigned to True, sdl history recordings will be included in snapshot.
                                                    Defaults to False.
        :param str coverage: (optional) snapshot coverage, allowed values: 'full', 'minor', 'fullWithoutRFLogs', 'minorWithoutRFLogs',
                             Defaults to 'full' which corresponds to All logs, 'minor' means most important logs
        :param str filter_regx: (optional) snapshot filter regular expression, default is None.

        :returns: operation id
        :rtype: str
        """
        return connection.trigger_local_snapshot(use_m2m=use_m2m, **kwargs)

    @lookup_handler.implicit_lookup
    def get_local_snapshot_by_id(self, directory, operation_id, request_timeout=None, operation_timeout=600.0,
                                 connection=None, use_m2m=True, compressed=True):
        """
        Gets local snapshot with given ID and saves it in given directory

        .. note::

           **API used:**

           +-------------------+-------------------------------------------------------------------+
           | use_m2m           | API Endpoint(s)                                                   |
           +===================+===================================================================+
           | True              | * `GET /api/licensed/v1/snapshot/operations/{operationId}`_       |
           |                   | * `GET /api/licensed/v1/snapshot/{operationId}/files/{fileId}`_   |
           |                   | * `DELETE /api/licensed/v1/snapshot/operations/{operationId}`_    |
           +-------------------+-------------------------------------------------------------------+
           | False             | * `GET /api/asm/v1/snapshot/operations/locals/{operationId}`_     |
           |                   | * `GET /api/asm/v1/snapshot/locals/{operationId}/files/{fileId}`_ |
           |                   | * `DELETE /api/asm/v1/snapshot/operations/locals/{operationId}`_  |
           +-------------------+-------------------------------------------------------------------+

        :param str directory: absolute directory path where snapshot files will be saved, for example: /home/ute/Snapshot
        :param str operation_id: ID of snapshot, can be taken from trigger_local_snapshot keyword output.
        :param Union[int, str, float] request_timeout: timeout in seconds for sending request to OAM, defaults to None
        :param Union[int, str, float] operation_timeout: timeout in seconds for getting snapshot, defaults to 600.0
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.
        :param bool use_m2m: (optional, applicable only for release cuoam_21b or newer) If set to False,
                             internal API will be used instead of licensed API (M2M).
                             Defaults to True.
        :param bool compressed: (optional) If True, all files will be compressed to one zip file. Defaults to True

        :raises SnapshotOperationIdNotFound: If given snapshot operation ID is not found.

        :returns: snapshot file path.
                  If snapshot files are compressed, the zip file path is returned. i.e. /home/ute/Snapshot_20230921-163838.zip.
                  If snapshot files are not compressed, the snapshot folder name is returned which is the same as parameter - directory.
        :rtype: str
        """
        return connection.get_local_snapshot_by_id(directory=directory,
                                                   operation_id=operation_id,
                                                   request_timeout=time_to_seconds(request_timeout) if request_timeout else None,
                                                   operation_timeout=time_to_seconds(operation_timeout),
                                                   use_m2m=use_m2m,
                                                   compressed=compressed)

