    @lookup_handler.implicit_lookup
    def update_parameters_of_delta_plan(self, plan_id, mo_uuid, parameter_change_list, connection=None):
        """
        Update parameters in a managed object

        .. important::
            This keyword was affected by CB012840 and is only usable for SW builds older than o vCUCNF25R2_0.250.27743

        .. note::
            **API used:**

            POST /api/asm/v1/delta-plans/{planId}/actions/update-parameters

        :param str plan_id: Identifier of the plan.
        :param str mo_uuid: managed object UUID to which the parameters should be applied.
        :param list parameter_change_list: list of dicts containing parameter change data, for example:

            .. code-block:: python

                [
                   {
                      "operation_type":"add",
                      "parameter_path":"/lssConfig/lssPortNo",
                      "value":"some_value"
                   }
                ]

            When adding nested parameter, parameter_change_list should be constructed as follows:

            .. code-block:: python

                [
                   {
                      "operation_type":"add",
                      "parameter_path":"/nrPlanDNList"
                   },
                   {
                      "operation_type":"add",
                      "parameter_path":"/nrPlanDNList/0"
                   },
                   {
                      "operation_type":"add",
                      "parameter_path":"/nrPlanDNList/0/parameter_name",
                      "value":"some_value"
                   }
                ]

            For an already existing structure:

            .. code-block:: python

                [
                   {
                      "operation_type":"add",
                      "parameter_path":"/nrPlanDNList/1"
                   },
                   {
                      "operation_type":"add",
                      "parameter_path":"/nrPlanDNList/1/parameter_name",
                      "value":"some_value"
                   }
                ]

        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.

        :returns: information about operation, for example:

            .. code-block:: python

                {
                  "action_id": 101,
                  "links": [
                    {
                      "rel": "self",
                      "herf": "/some/useful/links"
                    }
                  ],
                  "status": "ongoing",
                  "error_message": "error message"
                }
        :rtype: dict
        """
        return connection.update_parameters_of_delta_plan(plan_id, mo_uuid, parameter_change_list)

