    @lookup_handler.implicit_lookup
    def get_latest_validation_result_of_delta_plan(self, plan_id, error_type=None, timeout=30, connection=None,
                                                   **kwargs):
        """
        Get latest validation result of delta plan

        .. important::
            This keyword was affected by CB012840 and is only usable for SW builds older than o vCUCNF25R2_0.250.27743

        .. note::
            **API used:**

            GET /api/asm/v1/delta-plans/{planId}/validation-results/latest

        :param str plan_id: staged plan id
        :param str error_type: Available options: parameterRelationError, topologyDefinitionError, occurrenceDefinitionError,
                               parameterDefinitionError, topologyRelationError.
                               Default is None meaning all of the error types will be returned.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation in seconds
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.
        :param int page_number: (optional) active page number, default value is 1.
        :param int items_per_page: (optional) the number of items per page, default value is 20000.
        :param str sort_order: (optional) sorting order, available values : desc, asc, default value is desc
        :param str sorted_by: (optional) validation errors sorting criteria. Available values: parameterFullName,
                              parameterAbbreviation, parentDistName,default value is ''.

        :returns: errors, for example:

            .. code-block:: python

                {
                  "topology_definition_errors": [
                    {
                      "parent_dist_name": "MRBTS-0/EQM-X/APEQM-X",
                      "missing_class_name": "CABINET",
                      "parentMoUuid": "1234"
                    }
                  ],
                  "parameter_definition_errors": [
                    {
                      "mo_uuid": "1234",
                      "parameter_path": "btsName",
                      "error_description": "Missing required parameter",
                      "distname": "MRBTS-1/EQM-1/APEQM-1"
                    }
                  ],
                  "occurrence_definition_errors": [
                    {
                      "parent_mo_uuid": "1234",
                      "class_name": "MPLANENW",
                      "error_description": "Given value is too big. The maximum value of the parameter is 2."
                    }
                  ],
                  "topology_relation_errors": [
                    {
                      "error_index": "t1",
                      "error_description": "It is required that the set of MOs IPRT-*."
                    }
                  ],
                  "parameter_relation_errors": [
                    {
                      "mo_uuid": "123",
                      "nidd_id": "456",
                      "distname": "MRBTS-1/CLOCK-1",
                      "error_description": "Whenever * CLOCK-1.syncMaster (value: true) is equal to true",
                      "error_index": "p12345"
                    }
                  ],
                  "hardware_relation_errors": [
                    {
                      "mo_uuid": "123",
                      "nidd_id": "456",
                      "distname": "MRBTS-1/CLOCK_R-1",
                      "error_description": "Whenever * CLOCK_R-1.syncMaster (value: true) is equal to true",
                      "error_index": "p12345"
                    }
                  ]
                }
        :rtype: dict
        """
        validation_res = connection.get_latest_validation_result_of_delta_plan(plan_id=plan_id,
                                                                               error_type=error_type,
                                                                               timeout=time_to_seconds(timeout),
                                                                               **kwargs)
        if error_type:
            return {error_type: validation_res[error_type], 'total': validation_res['total']}
        return validation_res

