    @lookup_handler.implicit_lookup
    def update_rad_debug_params(self, persistency=None, domain_name=None, parameters=None, node_id=None, timeout=30,
                                connection=None, **kwargs):
        """
        Trigger Update of R&D Debug Parameters.
        When all arguments are None means Restore All Non-Default R&D Debug Parameters

        .. note::

           **API used:**

           +-------------------+------------------------------------------------------------------+
           | use_m2m           | API Endpoint                                                     |
           +===================+==================================================================+
           | True              | * `POST /api/licensed/v1/rads/debug-params/operations/updates`_  |
           +-------------------+------------------------------------------------------------------+
           | False             | * `POST /api/asm/v1/rads/debug-params/operations/updates`_       |
           +-------------------+------------------------------------------------------------------+

        :param str persistency: (optional) Available options: persistent, notPersistent or oneReset.
                                - persistent means persistent over all BTS resets.
                                - notPersistent means not persistent change.
                                - oneReset means persistent change over only one BTS reset.
                                Not providing persistency means persistent.
        :param str domain_name: (optional) Specify target domain name to update params in it.
                                Not providing this field means 'all available debug domains'
        :param list(dict) parameters: (optional) Params to be updated. Not providing any param means 'all params'.

                                      Argument parameters cannot be provided without domain_name.

                                      If user wants to change the value the list of dictionaries should be
                                      provided having both "name" and "value" keys for example:

                                      .. code-block:: python

                                        [
                                           {
                                              "name" : "LoggingLevel",
                                              "value" : "1 - Debug"
                                           },
                                           {
                                              "name": "rdTRSSloti",
                                              "value": 20
                                           }
                                        ]

                                      To restore to default value the "value" key should be omitted, for example:

                                      .. code-block:: python

                                        [
                                           {
                                              "name" : "LoggingLevel"
                                           },
                                           {
                                              "name": "rdTRSSloti"
                                           }
                                        ]

        :param int node_id: node id, default is None which means 'all nodes'
        :param Union[int, str, float] timeout: (optional) Timeout for the operation in seconds, defaults to 30
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.
        :param bool use_m2m: (optional) If set to False, internal API will be used instead of licensed API (M2M).
                             Defaults to True.
        :param bool raw: (optional) If set to True, the raw response will be returned.
                         Defaults to False.

        :returns: operation info, for example:

            .. code-block:: python

                {
                    'operation_id': '1672798968885076164',
                    'status': 'ongoing'
                }
        :rtype: dict
        """
        return connection.update_rad_debug_params(persistency=persistency,
                                                  node_id=node_id,
                                                  domain_name=domain_name,
                                                  parameters=parameters,
                                                  timeout=time_to_seconds(timeout),
                                                  **kwargs)

