    def get_login_response(self, username, connection=None):
        """
        Get login response info

        .. note::
            **API used:**

            GET /api/asm/v1/account/users/system

        :param str username: username for login
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.

        :returns: login response, for example:

            .. code-block:: python

                {
                    'lastLoginTime': '2021-11-05 06:28:10',
                    'TokenExpirationTime': '2021-11-05 06:59:28',
                    'PasswordExpirationTime': 'password never expires',
                    'InvalidLoginAttempts': 'There is no failed login attempt yet'
                }
        :rtype: dict
        """
        password_expiration_time = self.account_users_system_get(username=username, connection=connection)
        return {
            "lastLoginTime": convert_time_format(self.login_response.last_login_time),
            "TokenExpirationTime": convert_time_format(self.login_response.expires_time),
            "PasswordExpirationTime": convert_time_format(password_expiration_time['password_expiration_date']),
            "InvalidLoginAttempts": convert_time_format(self.login_response.failed_login_attempts)
        }

