    @lookup_handler.implicit_lookup
    def perform_delta_recommissioning(self, delta_file, wait_for_completion=True, should_activate=True, timeout=300,
                                      connection=None):
        """
        Perform delta recommissioning using JSON delta

        By default, wait_for_completion is set to True, meaning the keyword will wait until the operation is complete.
        If wait_for_completion is set to False, it is advisable to check the operation's status using
        get_status_of_perform_delta_recommissioning to confirm successful activation.

        .. note::

           **API used:**

           +---------------------+-------------------+--------------------------------------------------------------------------+
           | should_activate     | wait_for_completion | API Endpoints                                                          |
           +=====================+===================+==========================================================================+
           | True                | True              | POST /api/licensed/v1/delta-plans/operations/provisions;                 |
           |                     |                   | GET /api/licensed/v1/delta-plans/operations/provisions/{operationId}     |
           +---------------------+-------------------+--------------------------------------------------------------------------+
           | True                | False             | POST /api/licensed/v1/delta-plans/operations/provisions                  |
           +---------------------+-------------------+--------------------------------------------------------------------------+
           | False               | True              | POST /api/licensed/v1/delta-plans/operations/pre-activations;            |
           |                     |                   | GET /api/licensed/v1/delta-plans/operations/pre-activations/{operationId}|
           +---------------------+-------------------+--------------------------------------------------------------------------+
           | False               | False             | POST /api/licensed/v1/delta-plans/operations/pre-activations             |
           +---------------------+-------------------+--------------------------------------------------------------------------+

        :param str delta_file: Delta JSON or path JSON file, for example:

                               .. code-block:: python

                                   [
                                    {
                                        "distName": "MRBTS-1/LNBTS-1/LNMME-0",
                                        "operation": "update",
                                        "parameters": [
                                            {
                                                "parameterName": "ipAddrPrim",
                                                "value": "10.0.1.99",
                                                "operation": "update"
                                            },
                                            {
                                                "parameterName": "lssConfig",
                                                "operation": "delete"
                                            },
                                        ]
                                    }
                                ]

                               For more examples go to `Examples` section of documentation.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation in seconds, defaults to 300.
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
                                         Defaults to True.
        :param should_activate: (optional) If set to True, plan will be activated, otherwise it will be validated
                                           without activation. In order to activate the pre-activated plan user
                                           should call perform_delta_recommissioning again with should_activate=True.
                                           Defaults to True.
        :returns: status of the operation, for example:

            .. code-block:: python

                {
                  "id": "101234",
                  "status": "ongoing"
                }
        :rtype: dict
        """
        return connection.perform_delta_recommissioning(delta_file=delta_file,
                                                        wait_for_completion=wait_for_completion,
                                                        should_activate=should_activate,
                                                        timeout=time_to_seconds(timeout, round_to=0))

    @lookup_handler.implicit_lookup
    def get_status_of_perform_delta_recommissioning(self, operation_id, connection=None, timeout=30,
                                                    should_activate=True):
        """
        Get the status of perform_delta_recommissioning operation.
        If should_activate parameter was set to False when executing perform_delta_recommissioning, it
        should also be given as False to properly get the status.

        .. note::

           **API used:**

           +-------------------+---------------------------------------------------------------------------+
           | should_activate   | API Endpoints                                                             |
           +===================+===========================================================================+
           | True              | POST /api/licensed/v1/delta-plans/operations/provisions{operationId}      |
           +-------------------+---------------------------------------------------------------------------+
           | False             | POST /api/licensed/v1/delta-plans/operations/pre-activations/{operationId}|
           +-------------------+---------------------------------------------------------------------------+

        :param str operation_id: Operation ID of the delta recommissioning operation. Can be taken from
                                 perform_delta_recommissioning keyword response
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation in seconds, defaults to 30.
        :param bool should_activate: (optional) Should be set to False if  perform_delta_recommissioning
                                                was executed without activation. Defaults to True.
        :returns: status of the operation, for example:

            .. code-block:: python

                {
                  "id": "101234",
                  "status": "success"
                }
        :rtype: dict
        """
        return connection.get_status_of_perform_delta_recommissioning(operation_id=operation_id,
                                                                      should_activate=should_activate,
                                                                      timeout=time_to_seconds(timeout, round_to=0))

