    @lookup_handler.implicit_lookup
    def search_parameter_of_current_plan(self, para_name, mo_dn, connection=None):
        """
        Online search parameter from the current plan. Equivalent of the keyword with the same name from vDU library.
        Do not confuse this keyword with `search_parameters_of_current_plan`, as this one only returns value of given
        one parameter and not all current plan parameters.

        .. note::
            **API used:**

            * `GET /api/emservice/v1/delta-plans/{plan_id}/parameters`_

        :param str para_name: name of the parameter to search ("Abbreviation" column in Parameter Editor)
                              In case of complex parameters, the main parameter name, index and sub-parameter name
                              can be given separated by "/", for example:
                              - "csirsBeamMgmt/0/csirsBmMgmtReIndex", to get value of "csirsBmMgmtReIndex"
                              - "csirsBeamMgmt/0", to get whole 1st structure of "csirsBeamMgmt"
                              - "csirsBeamMgmt", to get all the structures under "csirsBeamMgmt"
        :param str mo_dn: distname of managed object to which parameter belongs, e.g. MRBTS-1/NRBTS-1/NRCELL-1
        :param Union[CUConnection, str] connection: (optional) Unique identifier for a certain connections or
                                                    CUConnection instance returned by connect_to.

        :return: the parameter value(s).
                 For simple parameters, and complex named parameters return value is a string, for exaple "Unblocked".
                 For simple list parameters, return value is a list of values, for example ["0", "1"]
                 For complex parameters, return value is a:
                 - string, for example "7" when `para_name` is in form of, for example: "guAMI/0/mnc"
                 - list of dictionaries in object, when `para_name` is in form of, for example: "guAMI/0". Example return:

                   .. code-block:: python

                     [
                       {
                         'value': '2',
                         'state': 'unchanged',
                         'name': 'amfPointer'
                       },
                       {
                         'value': '2',
                         'state': 'unchanged',
                         'name': 'amfRegionID'
                       },
                       {
                         'value': '7',
                         'state': 'unchanged',
                         'name': 'mnc'
                       }
                     ]

                 - list of lists of objects, when `para_name` is in form of, for example: "guAMI". Example return:

                   .. code-block:: python

                     [
                       [
                         {
                           'value': '2',
                           'state': 'unchanged',
                           'name': 'amfPointer'
                         },
                         {
                           'value': '2',
                           'state': 'unchanged',
                           'name': 'amfRegionID'
                         },
                         {
                           'value': '7',
                           'state': 'unchanged',
                           'name': 'mnc'
                         }
                       ],
                       [
                         {
                           'value': '2',
                           'state': 'unchanged',
                           'name': 'amfPointer'
                         },
                         {
                           'value': '2',
                           'state': 'unchanged',
                           'name': 'amfRegionID'
                         },
                         {
                           'value': '8',
                           'state': 'unchanged',
                           'name': 'mnc'
                         }
                       ]
                     ]
        :rtype: Union[str, list(str)]
        """
        return connection.search_parameter_of_current_plan(para_name=para_name, mo_dn=mo_dn)

